:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #edf4ef; color: #173526; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px; }
.app { width: min(100%, 620px); background: #fff; border: 1px solid #cfe0d4; border-radius: 18px; box-shadow: 0 16px 45px rgba(24, 70, 45, .12); padding: clamp(22px, 5vw, 42px); }
h1 { margin: 0; font-size: clamp(1.8rem, 5vw, 2.6rem); }
.intro { color: #536c5e; margin: 8px 0 28px; }
label { display: block; font-weight: 700; margin-bottom: 8px; }
.entry { display: flex; gap: 10px; }
input { flex: 1; min-width: 0; border: 2px solid #b9cebf; border-radius: 10px; padding: 12px 14px; font: inherit; }
input:focus { outline: 3px solid #a9dcc0; border-color: #207245; }
button { border: 0; border-radius: 10px; padding: 11px 16px; font: inherit; font-weight: 700; cursor: pointer; background: #207245; color: #fff; }
button:hover { background: #145c35; }
button:focus-visible { outline: 3px solid #efb64e; outline-offset: 2px; }
.summary { margin: 24px 0 12px; font-weight: 800; color: #185f39; }
.habit-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.habit { display: flex; align-items: center; gap: 12px; border: 1px solid #d7e5da; border-radius: 12px; padding: 12px; }
.habit.done .habit-name { text-decoration: line-through; color: #718078; }
.habit-name { flex: 1; overflow-wrap: anywhere; }
.toggle { background: #e2f1e7; color: #155d35; }
.delete { background: #f7e3e0; color: #8d2d25; }
.empty { text-align: center; color: #718078; padding: 20px 0 4px; }
@media (max-width: 520px) { .entry { flex-direction: column; } .habit { align-items: stretch; flex-wrap: wrap; } .habit-name { flex-basis: 100%; } }
@media (prefers-reduced-motion: no-preference) { button { transition: background-color .15s ease, transform .15s ease; } button:active { transform: translateY(1px); } }

(function (root) {
  'use strict';

  const STORAGE_KEY = 'generalvs-habits-v1';

  function normalizeText(value) {
    return String(value || '').trim().replace(/\s+/g, ' ');
  }

  function addHabit(habits, text, id) {
    const name = normalizeText(text);
    if (!name) throw new Error('Alışkanlık adı boş olamaz.');
    return [...habits, { id: String(id), name, done: false }];
  }

  function toggleHabit(habits, id) {
    return habits.map((habit) => habit.id === String(id) ? { ...habit, done: !habit.done } : habit);
  }

  function deleteHabit(habits, id) {
    return habits.filter((habit) => habit.id !== String(id));
  }

  function counts(habits) {
    const completed = habits.filter((habit) => habit.done).length;
    return { total: habits.length, completed, remaining: habits.length - completed };
  }

  function serializeHabits(habits) {
    return JSON.stringify(habits);
  }

  function parseHabits(raw) {
    try {
      const value = JSON.parse(raw || '[]');
      if (!Array.isArray(value)) return [];
      return value.filter((item) => item && typeof item.id === 'string' && typeof item.name === 'string' && typeof item.done === 'boolean');
    } catch (_) {
      return [];
    }
  }

  function saveHabits(storage, habits) {
    storage.setItem(STORAGE_KEY, serializeHabits(habits));
  }

  function loadHabits(storage) {
    return parseHabits(storage.getItem(STORAGE_KEY));
  }

  const api = { STORAGE_KEY, normalizeText, addHabit, toggleHabit, deleteHabit, counts, serializeHabits, parseHabits, saveHabits, loadHabits };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;

  if (!root || !root.document) return;
  const document = root.document;
  const form = document.querySelector('#habit-form');
  const input = document.querySelector('#habit-input');
  const list = document.querySelector('#habit-list');
  const summary = document.querySelector('#summary');
  const empty = document.querySelector('#empty');
  let habits = loadHabits(root.localStorage);

  function nextId() {
    return root.crypto && root.crypto.randomUUID ? root.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }

  function render() {
    const state = counts(habits);
    summary.textContent = `${state.total} alışkanlık · ${state.completed} tamamlandı · ${state.remaining} kaldı`;
    empty.hidden = state.total > 0;
    list.replaceChildren();
    habits.forEach((habit) => {
      const item = document.createElement('li');
      item.className = `habit${habit.done ? ' done' : ''}`;
      const name = document.createElement('span');
      name.className = 'habit-name';
      name.textContent = habit.name;
      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'toggle';
      toggle.dataset.action = 'toggle';
      toggle.dataset.id = habit.id;
      toggle.textContent = habit.done ? 'Geri al' : 'Tamamla';
      toggle.setAttribute('aria-label', `${habit.name}: ${toggle.textContent}`);
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete';
      remove.dataset.action = 'delete';
      remove.dataset.id = habit.id;
      remove.textContent = 'Sil';
      remove.setAttribute('aria-label', `${habit.name} alışkanlığını sil`);
      item.append(name, toggle, remove);
      list.append(item);
    });
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    try {
      habits = addHabit(habits, input.value, nextId());
      saveHabits(root.localStorage, habits);
      input.value = '';
      input.focus();
      render();
    } catch (_) {
      input.focus();
    }
  });

  list.addEventListener('click', (event) => {
    const button = event.target.closest('button[data-action]');
    if (!button) return;
    habits = button.dataset.action === 'toggle' ? toggleHabit(habits, button.dataset.id) : deleteHabit(habits, button.dataset.id);
    saveHabits(root.localStorage, habits);
    render();
  });

  render();
}(typeof window !== 'undefined' ? window : null));

'use strict';
const assert = require('node:assert/strict');
const app = require('./app.js');

assert.equal(app.normalizeText('  Su   iç  '), 'Su iç', 'metin temizlenir');
assert.throws(() => app.addHabit([], '   ', 'x'), /boş olamaz/, 'boş alışkanlık reddedilir');
const original = [];
const one = app.addHabit(original, 'Kitap oku', '1');
assert.equal(original.length, 0, 'ekleme girdiyi değiştirmez');
assert.deepEqual(one[0], { id: '1', name: 'Kitap oku', done: false }, 'alışkanlık eklenir');
const done = app.toggleHabit(one, '1');
assert.equal(done[0].done, true, 'tamamlandı durumu değişir');
assert.equal(one[0].done, false, 'değiştirme kopya üzerinde yapılır');
const two = app.addHabit(done, 'Yürü', '2');
assert.deepEqual(app.counts(two), { total: 2, completed: 1, remaining: 1 }, 'sayaç doğrudur');
assert.deepEqual(app.deleteHabit(two, '1').map((item) => item.id), ['2'], 'silme doğrudur');
assert.deepEqual(app.parseHabits(app.serializeHabits(two)), two, 'JSON turu kayıpsızdır');
assert.deepEqual(app.parseHabits('{bozuk'), [], 'bozuk kayıt güvenle boş liste olur');
const memory = { value: null, setItem(_key, value) { this.value = value; }, getItem() { return this.value; } };
app.saveHabits(memory, two);
assert.deepEqual(app.loadHabits(memory), two, 'localStorage turu çalışır');
